Local Ltac mem_after_store ::= mem_after_store_fast.


Notation PAD_W data n := [(data, data + n)]%Z (only parsing).

Definition padbits_exit (ra sp gp tp t0 t1 t2 s0 s1 a1 a3 a4 a7 s2 s3 s4 s5 s7 s8 s9 s10 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (data wpl h ha : Z) : machine_state -> Prop :=
  fun ms' => exists (a0' a2' a5' a6' s6' : word) (m' : mem) (ws' : list word),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0' a1 a2' a3 a4 a5' a6' a7 s2 s3 s4 s5 s6' s7 s8 s9 s10 (Z_to_bv 64 SHB) t3 t4 t5 t6)
             F (Z_to_bv 64 0x9e8c4) fc None m' (seg_rom asegs)
    /\ munch (PAD_W data (4 * (wpl * h))) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ u32arr asegs m' data ws' /\ Z.of_nat (length ws') = wpl * h /\ rw_cells asegs m' ha [C4 (Z_to_bv 64 h)].

Lemma padbits_rows : forall (k : nat) (i : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a1 a3 a5 a6 a7 s2 s3 s5 s7 s8 s9 s10 t3 t4 t5 t6 : word) F fc (m : mem)
    (data wpl h fw ha : Z) (ws : list word),
  Z.of_nat k = h - i -> 0 <= i -> (1 <= k)%nat -> 0 <= fw < wpl -> 0 < wpl <= 2^20 -> 0 < h <= 2^20 -> wpl * h <= 2^24 ->
  0 < data -> data mod 8 = 0 -> data + 4 * (wpl * h) <= 2^47 -> (data + 4 * (wpl * h) <= 0x7fff7000 \/ 0x10007fff8000 <= data) ->
  (data + 4 * (wpl * h) <= 0x10000 \/ SEGTOP_A <= data) ->
  0 < ha -> ha + 4 <= 2^47 -> (ha + 4 <= data \/ data + 4 * (wpl * h) <= ha) ->
  u32arr asegs m data ws -> Z.of_nat (length ws) = wpl * h -> acc asegs m data (4 * (wpl * h)) ->
  rw_cells asegs m ha [C4 (Z_to_bv 64 h)] -> mem_inv asegs m ->
  evt asegs (padbits_exit ra sp gp tp t0 t1 t2 s0 s1 a1 a3 (Z_to_bv 64 (wpl * 4)) a7 s2 s3 (Z_to_bv 64 ha) s5 s7 s8 s9 s10 t3 t4 t5 t6 F fc m data wpl h ha)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (data + 4 * (i * wpl + fw))) a1 (Z_to_bv 64 i) a3 (Z_to_bv 64 (wpl * 4)) a5 a6 a7
             s2 s3 (Z_to_bv 64 ha) s5 (Z_to_bv 64 (data + 4 * (i * wpl + fw))) s7 s8 s9 s10 (Z_to_bv 64 SHB) t3 t4 t5 t6)
        F (Z_to_bv 64 0x9e894) fc None m (seg_rom asegs)).
